#[cfg(test)]
mod checkpoint_route_tests {
    use super::*;
    #[test]
    fn later_lantern_updates_respawn_without_losing_earned_inventory() {
        let mut g = Game::new(true);
        g.motor = Character::new(feet(vec2(1410., 520.)));
        g.update(Input::default(), 1. / 120.);
        assert_eq!(g.checkpoints.index(), 1);
        g.motor = Character::new(feet(vec2(2050., 520.)));
        g.update(Input::default(), 1. / 120.);
        assert_eq!(g.checkpoints.index(), 2);
        let saved = g.checkpoints.snapshot();
        g.crumbles[0].step(1., true).unwrap();
        g.motor = Character::new(feet(vec2(2235., 520.)));
        g.update(Input::default(), 1. / 120.);
        assert_eq!(g.position(), vec2(2050., 520.));
        assert!(g.crumbles[0].solid());
        g.motor = Character::new(feet(vec2(1410., 520.)));
        g.update(Input::default(), 1. / 120.);
        assert_eq!(g.checkpoints.snapshot(), saved);
    }
}

#[cfg(test)]
mod session_tests {
    use super::*;

    const STEP: f64 = 1. / 120.;

    fn idle(game: &mut Game, elapsed: f64) -> f32 {
        game.advance(elapsed, |_| Input::default(), |_, _| {})
    }

    #[test]
    fn ready_waits_for_confirm_and_does_not_bank_startup_time() {
        let mut game = Game::new(false);
        let start = game.position();
        assert_eq!(game.session.state(), SessionState::Ready);
        assert_eq!(idle(&mut game, 60.), 0.);
        game.update(
            Input {
                direction: 1.,
                jump: true,
                jump_held: true,
            },
            STEP as f32,
        );
        assert_eq!(game.position(), start);
        assert_eq!(game.trial.elapsed(), 0.);
        assert_eq!(game.session.tick(), 0);
        game.menu(false, false, true);
        assert_eq!(game.session.state(), SessionState::Ready);
        assert!(!game.menu(false, true, false));
        assert!(game.session.is_playing());
        assert_eq!(idle(&mut game, 0.), 0.);
        idle(&mut game, STEP);
        assert_eq!(game.session.tick(), 1);
        assert_eq!(game.elapsed, STEP as f32);
    }

    #[test]
    fn zero_tick_frames_retain_jump_input_and_catchup_accepts_it_once() {
        let mut game = Game::new(true);
        idle(&mut game, STEP);
        let mut pending_jump = true;
        let mut sampled = 0;
        let mut input = |_: &Game| {
            sampled += 1;
            Input {
                jump: std::mem::take(&mut pending_jump),
                jump_held: true,
                direction: 0.,
            }
        };
        assert_eq!(game.advance(STEP * 0.25, &mut input, |_, _| {}), 0.);
        let mut takeoffs = 0;
        game.advance(STEP * 11.75, &mut input, |game, _| {
            takeoffs += usize::from(game.feedback.jumped);
        });
        assert_eq!(sampled, 12);
        assert!(!pending_jump);
        assert_eq!(takeoffs, 1);
        assert_eq!(game.jumps, 1);
        assert!(!game.motor.grounded);
    }

    #[test]
    fn pause_freezes_airborne_motion_trial_platforms_and_feedback_without_catchup() {
        let mut game = Game::new(true);
        idle(&mut game, STEP);
        game.advance(
            STEP,
            |_| Input {
                jump: true,
                jump_held: true,
                direction: 1.,
            },
            |_, _| {},
        );
        assert!(game.feedback.jumped);
        let before = (
            game.position(),
            game.velocity(),
            game.trial.elapsed(),
            game.platforms[5].x,
            game.jump_feedback,
            game.session.tick(),
        );
        game.menu(false, false, true);
        assert!(game.session.is_paused());
        assert_eq!(idle(&mut game, 120.), 0.);
        assert_eq!(
            (
                game.position(),
                game.velocity(),
                game.trial.elapsed(),
                game.platforms[5].x,
                game.jump_feedback,
                game.session.tick()
            ),
            before,
        );
        // Direct simulation calls respect the same pause gate.
        game.update(Input::default(), 0.1);
        assert_eq!(game.position(), before.0);
        assert_eq!(game.trial.elapsed(), before.2);
        game.menu(false, true, false);
        assert!(game.session.is_playing());
        assert_eq!(idle(&mut game, 0.), 0.);
        idle(&mut game, STEP);
        assert_eq!(game.session.tick(), before.5 + 1);
        assert!(game.trial.elapsed() > before.2);
        assert!(game.jump_feedback < before.4);
        assert_eq!(game.jumps, 1);
    }

    #[test]
    fn pause_discards_buffered_jump_and_restart_clears_the_entire_run() {
        let mut game = Game::new(true);
        game.motor = Character::new(feet(vec2(90., 510.)));
        game.advance(
            STEP,
            |_| Input {
                jump: true,
                ..Input::default()
            },
            |_, _| {},
        );
        assert!(game.motor.jump.buffer > 0.);
        game.menu(false, false, true);
        assert_eq!(game.motor.jump.buffer, 0.);
        game.menu(false, false, true);
        for _ in 0..60 {
            idle(&mut game, STEP);
        }
        assert_eq!(game.jumps, 0, "pause must cancel a pending landing jump");
        assert!(game.motor.grounded);

        game.embers = vec![(vec2(102., 540.), false); 3];
        idle(&mut game, STEP);
        assert_eq!(game.ember_inventory.count(1), 3);
        assert!(game.score.total() > 0);
        game.motor = Character::new(feet(vec2(1410., 520.)));
        idle(&mut game, STEP);
        assert_eq!(game.checkpoints.index(), 1);
        game.crumbles[0].step(1., true).unwrap();
        assert!(!game.crumbles[0].solid());
        game.respawn();
        assert_eq!(game.deaths, 1);
        idle(&mut game, STEP * 0.5);
        game.menu(false, false, true);
        assert!(game.menu(true, false, false));
        assert!(game.session.is_playing());
        assert_eq!(game.session.tick(), 0);
        assert_eq!(game.position(), vec2(90., 520.));
        assert_eq!(game.velocity(), Vec2::ZERO);
        assert_eq!(game.checkpoints.index(), 0);
        assert_eq!(game.ember_inventory.count(1), 0);
        assert_eq!(game.embers.len(), 12);
        assert!(game.embers.iter().all(|(_, collected)| !collected));
        assert_eq!(game.score.total(), 0);
        assert_eq!(game.deaths, 0);
        assert_eq!(game.jumps, 0);
        assert_eq!(game.trial.elapsed(), 0.);
        assert!(game.trial.splits().iter().all(Option::is_none));
        assert!(game.crumbles.iter().all(|platform| platform.solid()));
        assert_eq!(game.respawn_notice, 0.);
        assert_eq!(game.checkpoint_notice, 0.);
        assert_eq!(game.jump_feedback, 0.);
        assert_eq!(game.landing_feedback, 0.);
        assert!(!game.feedback.respawned);
        assert_eq!(
            idle(&mut game, STEP * 0.5),
            0.,
            "restart clears fractional clock debt"
        );
    }

    #[test]
    fn autoplay_completion_freezes_everything_and_confirm_starts_a_fresh_run() {
        let mut game = Game::new(true);
        let mut victories = 0;
        for _ in 0..600 {
            game.advance(1. / 30., Game::autoplay, |game, _| {
                assert_eq!(victories, 0, "no further tick runs after reaching the lift");
                victories += usize::from(game.feedback.won);
            });
            if game.won() {
                break;
            }
        }
        assert!(game.won());
        assert_eq!(game.deaths, 0);
        assert_eq!(victories, 1);
        assert_eq!(game.checkpoints.index(), 2);
        let before = (
            game.position(),
            game.trial.elapsed(),
            game.score.total(),
            game.session.tick(),
        );
        game.menu(false, false, true);
        assert!(game.won(), "pause cannot reopen the completed run");
        game.advance(
            60.,
            |_| panic!("terminal session must not sample gameplay"),
            |_, _| panic!("terminal session must not tick"),
        );
        game.update(Input::default(), 1.);
        assert_eq!(
            (
                game.position(),
                game.trial.elapsed(),
                game.score.total(),
                game.session.tick()
            ),
            before
        );
        assert!(game.menu(false, true, false));
        assert!(game.session.is_playing());
        assert!(!game.trial.finished());
        assert_eq!(game.score.total(), 0);
        assert_eq!(game.session.tick(), 0);
    }

    #[test]
    fn landing_and_checkpoint_feedback_fire_on_edges_and_do_not_repeat_while_standing() {
        let mut game = Game::new(true);
        game.motor = Character::new(feet(vec2(1410., 490.)));
        game.motor.velocity.y = -400.;
        let mut landings = 0;
        let mut checkpoints = 0;
        for _ in 0..120 {
            game.advance(
                STEP,
                |_| Input::default(),
                |game, _| {
                    landings += usize::from(game.feedback.landed);
                    checkpoints += usize::from(game.feedback.checkpoint);
                },
            );
        }
        assert_eq!(landings, 1);
        assert_eq!(checkpoints, 1);
        assert!(game.landing_strength > 0.5);
        assert!((game.landing_at.y - 560.).abs() < 0.01);
        assert_eq!(game.landing_feedback, 0.);
        assert!(game.checkpoint_notice > 0.);
        for _ in 0..240 {
            idle(&mut game, STEP);
        }
        assert_eq!(
            game.checkpoint_notice, 0.,
            "standing at a lantern does not retrigger its notice"
        );
    }
}

#[cfg(test)]
mod journey200_131 {
    use super::*;

    const DT: f32 = 1. / 120.;

    #[test]
    fn consecutive_fresh_presses_accept_the_earned_air_jump_once() {
        let mut game = Game::new(true);
        game.embers = vec![(vec2(102., 540.), false); 3];
        game.update(Input::default(), DT);
        assert_eq!(game.ember_inventory.count(1), 3);
        let press = Input {
            jump: true,
            jump_held: true,
            ..Input::default()
        };
        game.update(press, DT);
        assert_eq!(game.jumps, 1);
        game.update(press, DT); // A release/repress sampled between adjacent ticks.
        assert_eq!(game.jumps, 2);
        assert!(game.air_jump_used);
        assert!(game.feedback.jumped);
        assert!(game.motor.velocity.y > 500.);
        game.update(press, DT);
        assert_eq!(game.jumps, 2, "an unavailable air jump emits no takeoff");
        assert!(!game.feedback.jumped);
        for _ in 0..200 {
            game.update(
                Input {
                    jump_held: true,
                    ..Input::default()
                },
                DT,
            );
        }
        assert!(game.motor.grounded);
        assert_eq!(game.jumps, 2, "holding alone must never buffer a new jump");
        assert!(!game.air_jump_used);
    }

    #[test]
    fn controls_gate_cancels_a_buffered_landing_jump_without_overriding_manual_pause() {
        let mut game = Game::new(true);
        let mut input = PlayerInput::transient("emberline-controls-gate");
        game.motor = Character::new(feet(vec2(90., 510.)));
        game.update(
            Input {
                jump: true,
                ..Input::default()
            },
            DT,
        );
        assert!(game.motor.jump.buffer > 0.);
        input.sample(true);
        input.set_controls_open(true);
        game.gate_input(input.gameplay_active());
        assert_eq!(game.motor.jump.buffer, 0.);
        assert!(game.session.is_playing());
        let before = (game.position(), game.trial.elapsed(), game.session.tick());
        game.advance(
            f64::from(input.simulation_dt(60.)),
            |_| panic!("controls gate"),
            |_, _| {},
        );
        assert_eq!(
            before,
            (game.position(), game.trial.elapsed(), game.session.tick())
        );
        input.set_controls_open(false);
        input.sample(true);
        for _ in 0..60 {
            game.advance(f64::from(DT), |_| Input::default(), |_, _| {});
        }
        assert!(game.motor.grounded);
        assert_eq!(game.jumps, 0);
        game.menu(false, false, true);
        input.set_controls_open(true);
        input.sample(false);
        game.gate_input(input.gameplay_active());
        input.set_controls_open(false);
        assert!(game.session.is_paused());
    }

    #[test]
    fn coyote_and_landing_buffers_expire_without_ghost_jumps() {
        let mut game = Game::new(true);
        game.motor = Character::new(feet(vec2(600., 490.)));
        game.motor.jump.coyote = DT * 0.5;
        game.update(
            Input {
                jump: true,
                ..Input::default()
            },
            DT,
        );
        assert_eq!(game.jumps, 0);
        assert!(!game.feedback.jumped);
        game.motor = Character::new(feet(vec2(90., 120.)));
        game.update(
            Input {
                jump: true,
                ..Input::default()
            },
            DT,
        );
        assert!(game.motor.jump.buffer > 0.);
        for _ in 0..150 {
            game.update(Input::default(), DT);
        }
        assert!(game.motor.grounded);
        assert_eq!(game.jumps, 0);
        assert_eq!(game.motor.jump.buffer, 0.);
    }

    #[test]
    fn autoplay_rules_and_accepted_events_are_identical_under_every_visual_policy() {
        for policy in [
            FeedbackPolicy::new(true, false, 1.).unwrap(),
            FeedbackPolicy::new(false, true, 1.).unwrap(),
            FeedbackPolicy::new(true, true, 1.).unwrap(),
            FeedbackPolicy::new(false, false, 0.).unwrap(),
            FeedbackPolicy::new(false, false, 0.3).unwrap(),
        ] {
            let mut baseline = Game::new(true);
            let mut reduced = Game::new(true);
            let mut motion = EmberAnimation::new();
            let mut takeoffs = 0;
            let mut landings = 0;
            let mut checkpoints = 0;
            for frame in 0..1800 {
                let dt = [1. / 30., 0., 1. / 144., 1. / 60.][frame % 4];
                baseline.advance(dt, Game::autoplay, |_, _| {});
                apply_policy(&mut reduced, &mut motion, policy);
                reduced.advance(dt, Game::autoplay, |game, dt| {
                    motion.update(game, dt);
                    apply_policy(game, &mut motion, policy);
                    takeoffs += usize::from(game.feedback.jumped);
                    landings += usize::from(game.feedback.landed);
                    checkpoints += usize::from(game.feedback.checkpoint);
                });
                assert_eq!(baseline.position(), reduced.position());
                assert_eq!(baseline.velocity(), reduced.velocity());
                assert_eq!(baseline.session.state(), reduced.session.state());
                assert_eq!(baseline.session.tick(), reduced.session.tick());
                assert_eq!(baseline.trial.elapsed(), reduced.trial.elapsed());
                assert_eq!(baseline.score.total(), reduced.score.total());
                assert_eq!(
                    baseline.checkpoints.recovery(),
                    reduced.checkpoints.recovery()
                );
                assert_eq!(baseline.embers, reduced.embers);
                assert_eq!(baseline.platforms, reduced.platforms);
                assert_eq!(baseline.feedback.jumped, reduced.feedback.jumped);
                assert_eq!(baseline.feedback.landed, reduced.feedback.landed);
                assert_eq!(baseline.feedback.checkpoint, reduced.feedback.checkpoint);
                if reduced.won() {
                    break;
                }
            }
            assert!(reduced.won());
            assert_eq!(reduced.deaths, 0);
            assert!(takeoffs >= 7);
            assert!(landings >= 7);
            assert_eq!(checkpoints, 2);
            assert_eq!(reduced.checkpoints.recovery().current.index, 2);
            assert!(reduced.checkpoints.recovery().next.is_none());
            assert!(reduced.trial.splits().iter().all(Option::is_some));
        }
    }
}
